V=[['拉丁 vapor / vaporem','热气、蒸气'],['古法语 vapor、盎格鲁法语 vapour；也有拉丁直接借入','蒸气、湿气'],['中古英语 vapour → 现代 vapor / vapour','蒸气；现代区分气态物质与雾滴']]
EV=[V[0],['拉丁 ex- + vapor → evaporare；分词 evaporatus','使蒸气散出；蒸发']]
EVA=EV+[['英语 evaporate','蒸发；比喻逐渐消失']]
VI=[['拉丁 vapidus；相关词 vappa','走味、乏味的；淡而无味的酒'],['英语 vapid','先说饮料乏味，后说谈话、文章空洞无趣']]
VP=V+[['英语 vapor + -ize / -ise → vaporize / vaporise','变成蒸气或使气化']]
